mapper.select:
select *
from b_case_shuhe_user
where is_black = 'Y'
 and upload_date >= #{startDay}
  and upload_date < #{endDay}
group by mobile;

select *
from b_case_shuhe_user
where clc_usr_max_dx_rrt_end  >=  #{nowDay} or usr_forbid_call_end_tim  >=  #{nowDay}
order by id desc limit #{limitStart}, 2000;

select id, clc_usr_max_dx_rrt_end, usr_forbid_call_end_tim
from b_case_shuhe_user
where cell = #{cell}
  and (clc_usr_max_dx_rrt_end  <>  '' or usr_forbid_call_end_tim  <>  '') limit 1;
